fun firstNonRepeatingCharacter(input: String): Char {
    return input.groupingBy { it }.eachCount().let { counts -> input.first { counts[it] == 1 } }
}

fun firstNonRepeatingCharacter(input: String): Char {
    val counts = input.groupingBy { it }.eachCount()
    return input.firstOrNull { counts[it] == 1 } ?: '\u0000'
}

fun firstNonRepeatingCharacter(input: String): Char {
    val counts = mutableMapOf<Char, Int>()
    for (char in input) counts[char] = (counts[char] ?: 0) + 1
    for (char in input) if (counts[char] == 1) return char
    return '\u0000'

}

fun firstNonRepeatingCharacter(input: String): Char {
    return input.asSequence().groupingBy { it }.eachCount().let { counts -> input.first { counts[it] == 1 } }
}
